B = {n: load('.', n) for n in ['iterutils','dictutils']}
def call(m, f, *a, **k):
    try: return ('ok', f(m)(*a, **k))
    except Exception as e: return ('err', type(e).__name__)
random.seed(0)
diffs = set()
