    cmp('split_iter', lambda m: lambda *a, **k: list(m.split_iter(*a, **k)), L, random.choice([None,0,'a']))
    cmp('strip', lambda m: m.strip, L, random.choice([None,0,'a']))
    cmp('lstrip', lambda m: m.lstrip, L, random.choice([None,0,'a']))
    cmp('rstrip', lambda m: m.rstrip, L, random.choice([None,0,'a']))
    cmp('unique', lambda m: m.unique, L)
    cmp('redundant', lambda m: m.redundant, L, groups=random.choice([True,False]))
    cmp('one', lambda m: m.one, L)
    cmp('first', lambda m: m.first, L, default=5)
    cmp('same', lambda m: m.same, L)
    cmp('partition', lambda m: m.partition, L)
    cmp('partition key', lambda m: m.partition, L, lambda x: x == 0)
    cmp('partition strkey', lambda m: m.partition, L, 'real')
    cmp('bucketize', lambda m: m.bucketize, L)
    cmp('bucketize vt', lambda m: m.bucketize, L, value_transform=str, key_filter=lambda k: k)
    s, e, st = random.randint(-3,5), random.randint(-3,5), random.choice([1,2,-1,0.5,-0.5,0])
    cmp('frange', lambda m: m.frange, s, e, st)
    cmp('backoff', lambda m: m.backoff, random.randint(0,4), random.randint(0,40), count=random.choice([None,0,3]), factor=random.choice([1,2,3,0.5]))
    cmp('soft_sorted', lambda m: m.soft_sorted, [x for x in L if isinstance(x,int)], first=[1], last=[0])
    cmp('untyped_sorted', lambda m: m.untyped_sorted, L)
    cmp('flatten', lambda m: m.flatten, [L,[L,(1,)]])
    cmp('get_path', lambda m: m.get_path, {'a':[{'b':L}]}, random.choice(['a.0.b','a.1','a.0.b.0',('a',0,'b',1),'x']), default=None)
    cmp('remap', lambda m: m.remap, {'a':[L,{'b':tuple(L)}], 'c':set(x for x in L if x is not None)})
    cmp('remap drop', lambda m: lambda r: m.remap(r, visit=lambda p,k,v: v is not None), {'a':[L,{'b':tuple(L)}]})
    cmp('research', lambda m: lambda r: m.research(r, query=lambda p,k,v: v==0), {'a':[L,{'b':tuple(L)}]})
# dictutils OMD
def omd_ops(m, ops):
    o = m.OMD(); log = []
    for op, k, v in ops:
        try:
            if op=='add': o.add(k,v)
            elif op=='set': o[k]=v
            elif op=='del': del o[k]
            elif op=='pop': log.append(o.pop(k, None))
            elif op=='poplast': log.append(o.poplast(k, None))
            elif op=='popall': log.append(o.popall(k, None))
            elif op=='upd': o.update({k:v})
            elif op=='ue': o.update_extend([(k,v)])
            elif op=='sd': log.append(o.setdefault(k,v))
