            elif op=='cp': o = o.copy()
            elif op=='dc': o = copy.deepcopy(o)
            elif op=='sort': o = o.sorted()
        except Exception as e: log.append(type(e).__name__)
        log.append((list(o.items(multi=True)), list(o.keys()), list(o.values()), len(o), o.todict(multi=True)))
    return log
for i in range(300):
    ops = [(random.choice(['add','set','del','pop','poplast','popall','upd','ue','sd','inv','pk','cp','dc','sort']), random.choice('abc'), random.randint(0,3)) for _ in range(8)]
    ra, rb = omd_ops(A['dictutils'], ops), omd_ops(B['dictutils'], ops)
    if ra != rb:
        j = next(i for i,(x,y) in enumerate(zip(ra,rb)) if x!=y)
        print('OMD DIFF', ops[:j+1], '\n 25:', ra[j], '\n repo:', rb[j]); break
# OneToOne / ManyToMany
for i in range(300):
    ra=rb=None
    ops=[(random.choice(['set','del','pop','upd','inv','sd']), random.choice('abc'), random.randint(0,3)) for _ in range(8)]
    res=[]
    for M in (A,B):
        o=M['dictutils'].OneToOne(); log=[]
        for op,k,v in ops:
            try:
                if op=='set': o[k]=v
                elif op=='del': del o[k]
                elif op=='pop': log.append(o.pop(k,None))
                elif op=='upd': o.update({k:v})
                elif op=='inv': o.inv[v]=k
                elif op=='sd': log.append(o.setdefault(k,v))
            except Exception as e: log.append(type(e).__name__)
            log.append((sorted(o.items()), sorted(o.inv.items())))
        res.append(log)
    if res[0]!=res[1]: print('OTO DIFF', ops); break
print('done')
